<?php
namespace Delnavazan\Platform\Core\Application;
use Delnavazan\Platform\Core\Infrastructure\Repository\ProposalRepository; use Delnavazan\Platform\Core\Support\Identifier;
/** Proposal issue only: no acceptance, delivery, reservation, identity, or conversion authority. */
final class ProposalService {
    public function __construct(private ?ProposalRepository $repo=null,private ?TeacherAvailabilityAssentService $assents=null){$this->repo??=new ProposalRepository();$this->assents??=new TeacherAvailabilityAssentService();}
    public function issue(array $input,string $idempotencyKey):array{$this->authorize();$candidate=Normalizer::id($input['candidate_id']??null);$fingerprint=$this->fingerprint($input['arrangement_fingerprint']??null);$acceptBy=$this->utc($input['accept_by']??null);if($acceptBy<=gmdate('Y-m-d H:i:s'))throw new \InvalidArgumentException('Proposal acceptance deadline must be future');$family=Normalizer::id($input['family_id']??null,false);$key=$this->digest($idempotencyKey);$payload=hash('sha256',json_encode(array($candidate,$fingerprint,$acceptBy,$family),JSON_THROW_ON_ERROR));$actor=get_current_user_id();return $this->assents->consumeCurrentForFutureProposalIssuance($candidate,$fingerprint,function(object $assent,object $snapshot,array $context)use($family,$key,$payload,$acceptBy,$actor){$now=gmdate('Y-m-d H:i:s');$claim=$this->repo->claim($key,$payload,$now);if($claim->payload_digest!==$payload)throw new \InvalidArgumentException('Proposal idempotency key conflicts with a different issuance');if($claim->state==='completed'){ $v=$this->repo->version((int)$claim->proposal_version_id);if(!$v)throw new \RuntimeException('Proposal replay unavailable');return $this->result($v);}$objective=hash('sha256',json_encode(array($context['request']->id,$context['case']->id,$snapshot->prospective_subject_ref,$snapshot->course_id,$snapshot->unresolved_course_spec),JSON_THROW_ON_ERROR));$f=$family?$this->repo->family($family):$this->repo->familyByObjective((int)$context['case']->id,$objective);if(!$f){$id=$this->repo->createFamily(array('uid'=>Identifier::uid(),'booking_request_id'=>$context['request']->id,'coordination_case_id'=>$context['case']->id,'prospective_subject_ref'=>$snapshot->prospective_subject_ref,'course_id'=>$snapshot->course_id,'unresolved_course_spec'=>$snapshot->unresolved_course_spec,'objective_fingerprint'=>$objective,'state'=>'open','version'=>1,'created_at'=>$now,'created_by'=>$actor,'closed_at'=>null,'closed_by'=>null));$f=$this->repo->family($id);}if(!$f||(int)$f->booking_request_id!==(int)$context['request']->id||(int)$f->coordination_case_id!==(int)$context['case']->id||$f->objective_fingerprint!==$objective)throw new \InvalidArgumentException('Proposal Family is not compatible with frozen arrangement facts');$o=$this->repo->option((int)$f->id,(int)$context['teacher']->id);if(!$o){$id=$this->repo->createOption(array('uid'=>Identifier::uid(),'family_id'=>$f->id,'teacher_id'=>$context['teacher']->id,'candidate_id'=>$context['candidate']->id,'state'=>'open','version'=>1,'created_at'=>$now,'created_by'=>$actor,'closed_at'=>null,'closed_by'=>null));$o=$this->repo->option((int)$f->id,(int)$context['teacher']->id);}if(!$o||(int)$o->candidate_id!==(int)$context['candidate']->id)throw new \InvalidArgumentException('Teacher change requires a different Proposal Option');$prior=$this->repo->currentVersion((int)$o->id);$number=$this->repo->nextVersion((int)$o->id);$uid=Identifier::uid();$facts=array('assent'=>$assent->uid,'snapshot'=>$snapshot->uid,'fingerprint'=>$snapshot->arrangement_fingerprint,'accept_by'=>$acceptBy,'policy'=>'phase_2a2d_v1');$proposalFingerprint=hash('sha256',json_encode($facts,JSON_THROW_ON_ERROR));$id=$this->repo->createVersion(array('uid'=>$uid,'family_id'=>$f->id,'option_id'=>$o->id,'version_number'=>$number,'assent_id'=>$assent->id,'assent_snapshot_id'=>$snapshot->id,'booking_request_id'=>$context['request']->id,'coordination_case_id'=>$context['case']->id,'candidate_id'=>$context['candidate']->id,'teacher_id'=>$context['teacher']->id,'prospective_subject_ref'=>$snapshot->prospective_subject_ref,'course_id'=>$snapshot->course_id,'unresolved_course_spec'=>$snapshot->unresolved_course_spec,'delivery_mode'=>$snapshot->delivery_mode,'location_scope'=>$snapshot->location_scope,'frequency_per_week'=>$snapshot->frequency_per_week,'expected_duration_minutes'=>$snapshot->expected_duration_minutes,'schedule_constraints'=>$snapshot->schedule_constraints,'commencement_window_start'=>$snapshot->commencement_window_start,'commencement_window_end'=>$snapshot->commencement_window_end,'timezone'=>$snapshot->timezone,'conditions_code'=>$snapshot->conditions_code,'arrangement_fingerprint'=>$snapshot->arrangement_fingerprint,'proposal_fingerprint'=>$proposalFingerprint,'accept_by'=>$acceptBy,'policy_reference'=>'phase_2a2d_v1','state'=>'issued','superseded_by_version_id'=>null,'issued_at'=>$now,'issued_by'=>$actor,'created_at'=>$now));if($prior)$this->repo->supersede($prior,$id);$this->repo->complete($claim,$f->id,$o->id,$id,$uid,$now);$this->repo->audit($id,$actor,'family='.$f->id.';option='.$o->id.';version='.$number.';assent='.$assent->id,$this->digest('audit:'.$uid),$now);return array('family_id'=>(int)$f->id,'option_id'=>(int)$o->id,'proposal_version_id'=>$id,'version_number'=>$number,'uid'=>$uid,'idempotent'=>false);});}
    private function result(object $v):array{return array('family_id'=>(int)$v->family_id,'option_id'=>(int)$v->option_id,'proposal_version_id'=>(int)$v->id,'version_number'=>(int)$v->version_number,'uid'=>$v->uid,'idempotent'=>true);}
    private function authorize():void{if(!current_user_can('dzn_issue_proposals'))throw new \RuntimeException('Unauthorized');} private function fingerprint(mixed $v):string{$v=(string)$v;if(!preg_match('/^[a-f0-9]{64}$/D',$v))throw new \InvalidArgumentException('Arrangement fingerprint required');return$v;} private function utc(mixed $v):string{$v=(string)$v;$d=\DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$v,new \DateTimeZone('UTC'));if(!$d||$d->format('Y-m-d H:i:s')!==$v)throw new \InvalidArgumentException('Proposal acceptance deadline must be canonical UTC datetime');return$v;} private function digest(string $v):string{if(strlen($v)<16||strlen($v)>200)throw new \InvalidArgumentException('Proposal idempotency key required');return hash_hmac('sha256','proposal-issue:'.$v,wp_salt('dzn_proposal_issuance'));}
}
